<?php
declare(strict_types=1);

/** Versioned original explanations; independent of stored exercise IDs and progress. */
function study_chapter(string $slug): ?array
{
    static $chapters;
    $chapters ??= json_decode(file_get_contents(ROOT . '/content/books/chapters.json'), true, 512, JSON_THROW_ON_ERROR);
    return $chapters[$slug] ?? null;
}

function study_chapter_english(string $slug): ?array
{
    static $chapters;
    $chapters ??= json_decode(file_get_contents(ROOT . '/content/books/chapters_en.json'), true, 512, JSON_THROW_ON_ERROR);
    return $chapters[$slug] ?? null;
}

function study_english_unit_fallback(array $unit): array
{
    $slug = preg_replace('/^[a-c][1-2]-/', '', (string) ($unit['slug'] ?? 'english'));
    $title = ucwords(str_replace(['-', '_'], ' ', $slug));

    $rules = [
        [['mixed-conditionals', 'conditionals-mixed', 'wish'], 'Hypothetical situations and wishes', 'Explore unreal situations, past alternatives and wishes.', 'Identify the time of each condition and result before choosing a form.', 'Mixed conditionals connect different times. A past condition can have a present result, or a present situation can have an imagined past result. Wish + past form describes a present situation you want to change; wish + past perfect expresses past regret.', 'Use the second conditional for an unreal present or future, the third for an unreal past, and a mixed form when the two clauses refer to different times.', 'If I had taken the earlier train, I would be home now.', 'The past condition has a present result, so the clauses use different time forms.', 'Draw a simple timeline first. Check that the verb forms match the time and meaning of each clause.'],
        [['third-conditional', 'past-regrets', 'past-speculation'], 'Unreal past situations', 'Talk about a different result for a finished past event.', 'Describe what happened and imagine a different past result.', 'Use if + past perfect for the unreal condition. Use would have, could have or might have + past participle for the imagined result. These forms describe an alternative; they do not change what really happened.', 'Use the second conditional for a present or future situation. Use the third conditional when both the condition and result belong to a finished past.', 'If we had left earlier, we would have caught the train.', 'Had left is the unreal past condition. Would have caught is the imagined result.', 'Separate the real events from the alternative you imagine. Then match each verb form to its time.'],
        [['second-conditional', 'conditionals-2', 'conditionals-3'], 'Hypothetical conditionals', 'Compare real possibilities with imagined situations.', 'Choose a conditional form that matches how likely or real a situation is.', 'The second conditional uses if + past simple and would + base verb for an unreal or unlikely present or future. The third conditional uses if + past perfect and would have + past participle for an unreal past.', 'Do not use would in the if-clause in the standard pattern. Use the past form to show distance from reality, not necessarily past time.', 'If I had more time, I would learn another language.', 'Had describes an imagined present condition; would learn gives its result.', 'Decide whether the situation is real, imagined now or different from a finished past.'],
        [['first-conditional', 'zero-conditional', 'unless'], 'Conditions and results', 'Explain general rules and possible future results.', 'Connect a condition with the result that follows from it.', 'Use present simple in both parts for general facts. Use present simple after if and a suitable future form in the result for a real future possibility. Unless often means if not.', 'Do not normally put will directly after if. Use a comma when the condition comes first.', 'If the meeting finishes early, we will call you.', 'Finishes is present simple after if; will call gives the possible result.', 'Check that the result makes sense only when the condition is true.'],
        [['present-perfect-continuous'], 'Present perfect continuous', 'Describe an activity that started earlier and continues or has a present result.', 'Choose between focus on an activity and focus on its result.', 'Form it with have/has been + -ing. Use it for an activity continuing up to now or for a recent activity with a visible result. Use for to give a duration and since to give a starting point.', 'The present perfect simple often focuses on a result or amount completed. The continuous form highlights the activity or its duration.', 'She has been studying for three hours.', 'Has been studying focuses on the activity and how long it has continued.', 'Ask whether the message focuses on the action, its duration or its completed result.'],
        [['present-perfect', 'for-since', 'already-yet'], 'Present perfect', 'Connect an earlier event or continuing situation with now.', 'Choose the present perfect for experience, present results and situations that continue.', 'Form it with have/has + past participle. Use for with a length of time and since with a starting point. Use already for something completed before now and yet in many questions and negatives.', 'Use the past simple with a finished time such as yesterday or in 2022. Do not combine the present perfect with a specific finished time.', 'I have lived here since 2021.', 'Since 2021 gives the starting point of a situation that continues now.', 'Look at the time frame: experience up to now, an unfinished period or one finished event.'],
        [['past-continuous', 'narrative-tenses'], 'Past continuous and narrative tenses', 'Set a scene and show what happened during an activity.', 'Use different past forms to organise a story.', 'Use was/were + -ing for an action in progress in the past. Use the past simple for a complete event. Use the past perfect for an event that happened before another past event.', 'The longer action is not always continuous; choose the form by how you present it. Use time words to show the order when needed.', 'I was walking home when I saw the lights.', 'Was walking sets the scene; saw marks the event that happened during it.', 'Mark the background, the main event and any earlier event before choosing a tense.'],
        [['past-perfect'], 'Past perfect', 'Show that one past event happened before another.', 'Place two events in a clear order in the past.', 'Form the past perfect with had + past participle. Use it for the earlier of two past events when the order is not already clear. The later event usually uses the past simple.', 'Use the past simple for a sequence that is already clear. The past perfect adds a clear link to an earlier time.', 'The train had left before we reached the station.', 'Had left happened first; reached happened later.', 'Use the past perfect to guide the reader back from a past point to an earlier event.'],
        [['past-simple', 'past-time'], 'Past simple and past time', 'Describe finished events and their sequence.', 'Use past forms and time markers to tell what happened.', 'Use the past simple for complete events in a finished period. Regular verbs often add -ed; irregular verbs have their own form. Use did + base verb in questions and negatives.', 'After did or didn't, do not use the past form of the main verb. Use was/were directly with be.', 'Where did they stay last night? They stayed near the airport.', 'Did marks the past in the question, so stay is in its base form.', 'Add time words and sequence markers so the reader can follow the events.'],
        [['future-perfect'], 'Future perfect', 'Describe what will be complete before a future time.', 'Place a finished action before a point in the future.', 'Form it with will have + past participle. Use it with by + a future time to say that an action will be complete by then.', 'Use the future simple for a future event without highlighting completion before a deadline.', 'By Friday, we will have finished the report.', 'By Friday sets the future point; will have finished shows completion before it.', 'Find the future deadline first, then identify what will be complete by that time.'],
        [['future', 'going-to', 'will', 'offers-promises', 'predictions', 'arrangements'], 'Future forms', 'Talk about plans, arrangements, offers and predictions.', 'Choose a future form based on how the event is planned or predicted.', 'Use going to for an earlier intention or a prediction based on evidence. Use will for a decision made now, an offer, a promise or a prediction based on belief. Use the present continuous for a fixed arrangement.', 'All these forms refer to the future, but they show a different point of view. Include a time phrase when it helps.', 'Look at those clouds. It is going to rain.', 'The visible clouds are present evidence for the prediction.', 'Ask whether the idea was planned earlier, arranged with someone or decided now.'],
        [['reported-questions', 'indirect-questions', 'reported-requests', 'reported-speech'], 'Reported speech and questions', 'Report what someone said or asked from a new point of view.', 'Keep the message clear when you report another person's words.', 'After a past reporting verb, verb forms often move back one step. Pronouns and time words may also change. Reported questions use statement word order; yes/no questions use if or whether.', 'Say does not take a person directly after it; tell usually does. Do not keep question inversion inside an indirect question.', 'She asked where the meeting was.', 'The reported clause uses subject before verb, not question word order.', 'Check who spoke, who listened and when the message is reported before changing pronouns or time words.'],
        [['relative', 'noun-clauses'], 'Relative and noun clauses', 'Join ideas and make the relationship between them clear.', 'Use clauses to identify a noun or report an idea.', 'Relative clauses follow a noun and add information. Use who for people, which for things and whose for possession. Noun clauses can report a question or idea and usually use statement word order.', 'A defining relative clause identifies which person or thing you mean. A non-defining clause adds extra information and uses commas.', 'The person who called left a message.', 'Who introduces information that identifies the person.', 'Keep each clause close to the word or idea it explains.'],
        [['passive', 'causative'], 'Passive and causative forms', 'Focus on a process, result or service done by another person.', 'Choose whether the sentence should focus on the agent or the result.', 'Form the passive with be + past participle. Change be to show the tense. Use have/get something done when another person performs a service for you.', 'Use active voice when the person doing the action matters. Use by + agent in a passive sentence only when the agent is useful.', 'The office is cleaned every evening.', 'The passive makes the office the topic and does not name the cleaner.', 'Check who acts, who receives the action and what the reader needs to notice.'],
        [['modals', 'modal', 'shouldnt', 'obligations', 'must-vs', 'ability-past', 'permission-requests'], 'Modal verbs', 'Express ability, advice, permission, obligation or possibility.', 'Choose a modal that matches the strength and purpose of the message.', 'Modal verbs such as can, could, may, might, must and should come before a base verb. They do not take -s with he or she. The negative form can change the meaning.', 'Mustn't means something is forbidden; don't have to means it is optional. Could often makes a request more polite than can.', 'You should check the time, but you don't have to arrive early.', 'Should gives advice; don't have to says that early arrival is not required.', 'Decide whether the action is possible, required, forbidden, optional or recommended.'],
        [['gerund', 'infinitive', 'verbs-ing'], 'Gerunds and infinitives', 'Choose the form that follows a verb or preposition.', 'Learn common verb patterns as part of the meaning.', 'Some verbs take -ing, such as enjoy doing. Others take to + base verb, such as decide to do. After a preposition, use -ing when a verb follows. Some verbs accept both forms with a change in meaning.', 'Do not choose the form by translating the Spanish infinitive. Learn each verb with its complement and an example.', 'She enjoys reading and wants to write a story.', 'Enjoys is followed by -ing; wants is followed by to + base verb.', 'Record the verb, its pattern and a complete sentence together.'],
        [['comparative', 'superlative', 'as-as'], 'Comparisons', 'Compare people, things and changes using clear criteria.', 'Choose comparative or superlative forms and explain the feature.', 'Use -er or more + adjective to compare two things, and -est or the most to compare one item with a group. Use as…as for equal degree. Some forms are irregular, such as good/better/best.', 'Do not combine more with -er. Use than for the second item and identify the group for a superlative.', 'This route is shorter than the old one, but the train is the fastest option.', 'Shorter compares two routes; fastest compares an option with a group.', 'Name the feature you compare, such as cost, speed or comfort.'],
        [['quantifier', 'countable', 'uncountable', 'few-little'], 'Nouns and quantity words', 'Choose quantity expressions that match the noun.', 'Describe amounts and distinguish countable from uncountable nouns.', 'Countable nouns have singular and plural forms. Uncountable nouns describe substances or ideas. Use many/a few with countable plurals and much/a little with uncountable nouns. Add a unit when you need to count a substance.', 'Some nouns can be countable or uncountable in different meanings. The article a changes the tone in few/little expressions.', 'We have a few chairs and a little time.', 'Chairs can be counted; time is uncountable.', 'Identify the main noun before choosing an article or quantity word.'],
        [['article', 'determiner'], 'Articles and determiners', 'Show whether a noun is new, known or general.', 'Choose an article or determiner by the meaning of the noun phrase.', 'Use a/an for one new singular countable noun, the for an identifiable item, and no article for many general plural or uncountable nouns. Other determiners such as this, those and each give more information.', 'Choose a/an by sound, not spelling. Do not use a/an with a plural noun or an uncountable noun.', 'I bought a map. The map shows every bus route.', 'A map introduces a new item; the map refers to that known item.', 'Ask whether the reader can identify the noun and whether it can be counted.'],
        [['adjective', 'adverb'], 'Adjectives and adverbs', 'Describe people, things and the way actions happen.', 'Choose a describing word that fits the word it modifies.', 'Adjectives describe nouns or follow be: a quiet room, the room is quiet. Adverbs often describe verbs and may end in -ly: speak quietly. Some adverbs are irregular, such as well and fast.', 'Use an adjective for a person or thing and an adverb for an action. Fast can be both, depending on its role.', 'She is careful, and she drives carefully.', 'Careful describes she; carefully describes how she drives.', 'Find the word being described, then choose adjective or adverb form.'],
        [['phrasal'], 'Phrasal verbs', 'Understand common verb + particle expressions.', 'Learn the meaning and word order of common phrasal verbs.', 'A phrasal verb combines a verb with a particle such as up, off or out. The full phrase has its own meaning. Some are separable; with a pronoun, the object usually goes between the verb and particle.', 'Other phrasal verbs cannot be separated. Learn each one with its object and an example instead of translating the parts alone.', 'Please turn the light off. Please turn it off.', 'The object it goes between turn and off.', 'Record the whole phrase and notice whether an object can move.'],
        [['collocation', 'idiom', 'make-do-have'], 'Collocations and expressions', 'Use natural word combinations in everyday and formal English.', 'Learn common words as complete combinations.', 'Some words commonly appear together: make a decision, do homework, heavy rain. These collocations are part of vocabulary. Idioms have a meaning that may not be clear from the separate words.', 'Do not translate word combinations literally. Check the situation and level of formality before using an idiom.', 'We made a decision after a long discussion.', 'Make a decision is the natural collocation.', 'Record the phrase, its meaning and a context where it is appropriate.'],
        [['linker', 'discourse-marker', 'connector'], 'Linking words and discourse markers', 'Show how one idea connects to another.', 'Choose a connector that matches the logic of the sentence.', 'Use linkers to add, contrast, give a reason, show a result or concede a point. Although introduces a clause; despite is followed by a noun or -ing form. However usually starts a new sentence or follows a semicolon.', 'A connector does not make two ideas logical by itself. Use it only when the relationship is accurate.', 'Although the task was difficult, the team finished on time.', 'Although introduces the unexpected contrast between difficulty and success.', 'Check the relationship between ideas first, then choose the linker and punctuation.'],
        [['preposition', 'movement'], 'Prepositions of time, place and movement', 'Describe when something happens and how people move.', 'Choose a preposition that matches the time, place or path.', 'At often marks an exact time or point, on marks days or surfaces, and in marks longer periods or enclosed spaces. Movement words such as into, across and through describe a path.', 'At/in usually describe a location; into/out of describe movement. Learn common combinations as phrases.', 'The meeting starts at nine. Walk through the park to the station.', 'At gives an exact time; through describes the route.', 'Picture the time or path as you choose the preposition.'],
        [['inversion'], 'Inversion for emphasis', 'Use marked word order to highlight an idea.', 'Recognise and use inversion after selected negative or limiting expressions.', 'After expressions such as rarely, never or only after at the start of a clause, an auxiliary can come before the subject. If there is no auxiliary, use do/does/did and the base verb. The structure is emphatic and often formal.', 'Not every sentence beginning with only uses inversion. Check which clause is limited and keep the main verb in the correct form.', 'Only after the call did we understand the problem.', 'Did moves before the subject; understand stays in the base form.', 'Compare the neutral order with the inverted order and use inversion only when the focus helps.'],
        [['cleft', 'fronting'], 'Cleft sentences and fronting', 'Control which part of a sentence receives emphasis.', 'Reorder information to guide the reader’s attention.', 'A cleft sentence highlights a part: It was the timing that caused the delay. A what-cleft can highlight a need: What we need is more time. Fronting moves information to the beginning for contrast or connection.', 'These structures change the focus, not necessarily the facts. Use them when the context makes the focus useful.', 'It was the location that made the meeting difficult.', 'The cleft highlights location as the important factor.', 'Ask what question the sentence answers before choosing a marked structure.'],
        [['hedging', 'stance', 'certainty', 'uncertainty'], 'Hedging and certainty', 'Match the strength of a claim to the available evidence.', 'Express a careful view without making the message vague.', 'Use may or might for possibility, appears to for an observation, and tends to for a pattern. Limit a claim with phrases such as in this sample or under these conditions. Separate what was observed from what you infer.', 'A correlation does not prove a cause. Avoid stacking several hedges that make the claim unclear.', 'In this sample, regular practice was associated with higher scores.', 'In this sample limits the claim; associated with avoids saying that one thing caused the other.', 'State what the evidence supports and what remains uncertain.'],
        [['reading', 'literary', 'forensic'], 'Reading and interpretation', 'Find the main idea, evidence and point of view in a text.', 'Read critically and distinguish facts from interpretation.', 'Start with the title and purpose. Identify the main claim, then find the evidence and examples that support it. Notice contrast words, references and the writer’s point of view. Use context to infer unfamiliar vocabulary.', 'An example is not always proof of a general claim. Separate what the text says from what you infer.', 'The writer claims that the change saved time and supports it with two examples.', 'The claim and the supporting examples are different parts of the argument.', 'Ask who wrote the text, what it claims and what evidence is available.'],
        [['listening'], 'Listening for key information', 'Understand the purpose and details in spoken English.', 'Listen for the information needed in a conversation or announcement.', 'First identify the situation and main topic. Then listen for names, times, places, numbers and the speaker’s request or decision. Use familiar words and context to predict what may come next.', 'Do not try to translate every word during the first listen. Listen again for one specific detail and confirm it.', 'The announcement says the 8:15 train leaves from platform three.', 'The time, transport and platform are the key details.', 'Set a listening goal before you listen: main idea, time, place or action.'],
        [['writing', 'essay', 'email', 'summary', 'complaint', 'application'], 'Writing for a clear purpose', 'Organise a message for its reader and goal.', 'Write a clear text with a useful structure and suitable tone.', 'Identify the reader and purpose before writing. Put the main point near the beginning, group related details and use linkers to guide the reader. In a formal message, make the request or recommendation explicit and close appropriately.', 'A personal message can sound informal; a workplace or academic text needs a more controlled tone. Do not add complex words when a simple one is clearer.', 'I am writing to request a new appointment because I cannot attend on Tuesday.', 'The purpose appears at the start; because gives a clear reason.', 'Revise for purpose, order, clarity and tone, not only grammar.'],
        [['speaking', 'debate', 'interview', 'oral', 'discussion'], 'Speaking and interaction', 'Express an idea and respond clearly to another speaker.', 'Build a clear spoken answer and keep the conversation moving.', 'State your main idea first. Add one reason or example, then listen to the response. Use phrases such as I think, because, for example and I see your point to organise a turn and show how you respond.', 'Disagreement can be clear and respectful. Do not interrupt; acknowledge the other view before you explain your reason.', 'I see your point, but I would choose the earlier option because it is safer.', 'The speaker acknowledges a view, states a different choice and gives a reason.', 'A useful spoken turn answers the question, supports the point and invites a reply.'],
        [['argument', 'rhetoric', 'editorial', 'counterargument', 'fallac'], 'Argument and counterargument', 'Present a claim, support it and respond to another view.', 'Build a reasoned argument that a reader can follow.', 'State a clear claim, support it with relevant evidence and explain how the evidence connects to the claim. A counterargument presents a different view; a response explains its limits or offers a reason to prefer your position.', 'Do not attack a person instead of answering the idea. Separate evidence, interpretation and conclusion.', 'Some people prefer the new schedule because it is flexible; however, it may not suit workers with fixed shifts.', 'The sentence presents a reason and then limits it with a counterpoint.', 'A strong argument shows both the claim and the reasoning behind it.'],
        [['academic', 'research', 'methodology', 'scientific', 'statistical', 'data', 'evidence'], 'Evidence and academic claims', 'Describe findings carefully and show their limits.', 'Present evidence without claiming more than it supports.', 'State the source or sample, report the finding, and explain what it may mean. Distinguish observation from cause. Use cautious phrases such as the results suggest and in this study when the evidence is limited.', 'A small sample may not represent everyone. A relationship between two things does not by itself show that one caused the other.', 'The survey found higher scores in this group, but it does not show why they were higher.', 'The sentence reports a finding and states a limit on the explanation.', 'Separate data, interpretation and recommendation so the reader can judge each one.'],
        [['policy', 'contract', 'legal', 'regulatory', 'judicial'], 'Policy and formal documents', 'Read and write precise rules, requirements and recommendations.', 'Identify responsibilities, conditions and consequences in formal texts.', 'Look for who must act, what action is required, when it applies and what happens if the condition is not met. Modal verbs such as must, may and should show different levels of obligation, permission and advice.', 'Must states a strong requirement; may gives permission or possibility; should is usually a recommendation. Check definitions and exceptions before drawing a conclusion.', 'Applicants must submit the form before the stated deadline.', 'Must states a requirement, and before gives its time limit.', 'Formal language is clear when responsibility, scope and timing are explicit.'],
        [['negotiation', 'diplomatic', 'mediation', 'cross-cultural', 'concession'], 'Negotiation and mediation', 'Express interests, explore options and reach a clear agreement.', 'Use language that keeps a discussion respectful and productive.', 'State the need behind your position, ask about the other person’s priorities and offer options. Use could, might and would to make proposals. Summarise points of agreement and confirm the next step.', 'A concession gives ground on one point but does not mean accepting everything. Check that both people understand the final agreement.', 'We could move the meeting to Thursday if the report is ready by then.', 'Could introduces an option; if states the condition for the agreement.', 'Separate positions from interests and make any condition explicit.'],
        [['risk', 'crisis', 'incident', 'safety'], 'Risk and incident communication', 'Describe a problem, its impact and the next action.', 'Report facts clearly and avoid unsupported conclusions.', 'State what happened, when and where. Describe the known impact and separate it from what is still being checked. Use sequence words for events and modals for actions that may be needed.', 'Do not present a possible cause as a confirmed fact. Identify who is responsible for the next action and when an update is expected.', 'The system stopped at 10:15. No data loss has been confirmed; the team is checking the backup.', 'The message separates a known event from a cause that is still under review.', 'In a report, distinguish confirmed facts, current actions and open questions.'],
        [['meeting', 'workplace', 'customer', 'professional', 'supply-chain', 'technical'], 'Professional communication', 'Give clear updates and requests in a workplace situation.', 'Organise information for a colleague, client or team.', 'Lead with the purpose, provide the key facts and state the action needed. Use polite requests and clear time references. Summarise decisions so everyone knows who will do what next.', 'A report gives information; a request asks someone to act. Keep the tone professional and avoid vague words such as soon when a date is known.', 'The shipment is delayed until Thursday. Could you update the customer today?', 'The first sentence gives the status; the second asks for a clear action.', 'Professional communication is useful when responsibilities and deadlines are easy to identify.'],
        [['checkpoint', 'assessment', 'evaluation', 'final-review', 'final-assessment'], 'Review and assessment', 'Review the unit topic and apply it in a new situation.', 'Check both the form and meaning of the language you have learned.', 'Review the main structure, its purpose and a model example. Then create a new example with different words. Check the subject, time, word order and the relationship between clauses.', 'Do not memorise one example as a fixed answer. Use the rule to build a new sentence that fits the context.', 'The team has finished the report, so it will send it tomorrow.', 'The sentence connects a completed action with a future result.', 'A useful review shows that you can transfer a rule to new information.'],
        [['ambiguity', 'implicature', 'presupposition', 'euphemism', 'subtext'], 'Meaning beyond the words', 'Notice how context changes what a message suggests.', 'Separate literal meaning from implied meaning and hidden assumptions.', 'Interpret a statement using its words, context, speaker and audience. Identify what is stated directly, what is assumed and what the listener is expected to infer. Check whether another reasonable interpretation is possible.', 'An implication is not always a fact. A speaker may suggest an idea without saying it directly, so support your interpretation with context.', 'The manager said the plan was “ambitious” after hearing about its cost.', 'The word may express approval or concern; context and tone help decide.', 'Explain the evidence for an interpretation and keep it separate from the literal wording.'],
        [['literary', 'metaphor', 'satire', 'humour', 'irony'], 'Literary style and interpretation', 'Interpret voice, tone and figurative meaning in a text.', 'Explain how word choice and structure affect a reader.', 'Notice who is speaking, what they know and how the language shapes the reader’s response. A metaphor describes one idea through another. Irony or humour may depend on a gap between words and context.', 'Do not treat a figurative phrase as literal. Use evidence from the text to support an interpretation of tone or meaning.', 'The writer calls the empty office a “quiet city.”', 'The phrase compares the office to a city and creates an image of space and silence.', 'Name the language feature, cite the detail and explain its effect.'],
        [['technology', 'ethical', 'ethical-ai'], 'Technology and ethical discussion', 'Discuss a technology choice, its benefits and its risks.', 'Present a balanced view and support it with clear reasons.', 'Describe what the technology does, who may benefit and who may be affected. Separate a factual claim from a value judgement. Use may or could for possible effects and give an example or source for an important claim.', 'A useful discussion considers both benefits and limits. Avoid saying that one example proves a general effect.', 'The tool may save time, but its use could expose personal information.', 'May and could mark possible effects; but introduces a concern.', 'Explain the benefit, the risk and the conditions that would reduce the risk.'],
        [['checkpoint', 'assessment', 'review', 'evaluation'], 'Review and application', 'Review the topic and apply it in a new context.', 'Use the key idea independently and explain your choice.', 'Identify the main concept, the evidence or example that supports it, and the language pattern used to express it. Then apply the same idea to a new case and explain what changes.', 'Do not repeat a memorised model without checking the new context. Keep the core rule and adapt the details.', 'The same policy may work in one setting but need changes in another.', 'The example transfers an idea while recognising that context can change the result.', 'A strong review shows understanding, not only recall.'],
        [['possessive-pronouns'], "Possessive pronouns", "Show who owns or is connected with something.", "Choose between possessive adjectives and possessive pronouns.", "Use my, your, his, her, its, our and their before a noun: their plan. Use mine, yours, his, hers, ours and theirs without a noun: the plan is theirs. Possessive forms do not use an apostrophe.", "A possessive adjective needs a noun after it; a possessive pronoun replaces the noun phrase. Its shows possession, while it's means it is or it has.", "Our room is next to theirs.", "Our comes before room; theirs replaces their room.", "Find the noun first. If it is already clear, a possessive pronoun can avoid repeating it."],
        [['possibility-might-may'], "Possibility and degrees of certainty", "Express how certain or uncertain a statement is.", "Choose a modal that matches the evidence and your level of confidence.", "May and might introduce possible situations. Could can describe a possible explanation or outcome. Add a reason or evidence when the listener needs to understand why you think something is possible.", "Must can express a strong deduction; may, might and could leave room for other explanations. Do not present a possibility as a confirmed fact.", "The delivery may arrive today, but the tracking page is not updated.", "May marks a possibility and the second clause explains the limit of the available information.", "Match the strength of the modal to the strength of the evidence."],
        [['tags-short-responses'], "Question tags and short responses", "Check information and respond naturally in conversation.", "Form question tags and short answers with the correct auxiliary.", "A positive statement usually takes a negative tag, and a negative statement usually takes a positive tag. Repeat the auxiliary in the tag. Short answers use the same auxiliary: Yes, I do; No, she isn't.", "Use the pronoun in the tag, not the noun. With I am, the common tag is aren't I?", "You work nearby, don't you? Yes, I do.", "The statement is positive and uses do, so the tag is negative and repeats do.", "Listen for the main auxiliary before forming the tag or short answer."],
        [['too-enough'], "Too and enough", "Describe limits, suitability and degree.", "Place too and enough correctly with adjectives, adverbs and nouns.", "Too comes before an adjective or adverb and means more than is suitable. Enough comes after an adjective or adverb, but before a noun. Use adjective + enough + to-infinitive to describe ability or suitability.", "Too often signals a problem; very only describes a high degree. Enough means the required amount or degree has been reached.", "The box is too heavy to carry, but the handle is strong enough.", "Too heavy gives a problem; strong enough gives a sufficient quality.", "Ask whether the degree is excessive or sufficient, then place the word in the correct position."],
        [['used-to-habits'], "Past habits with used to", "Compare a past routine or state with life now.", "Use used to for past habits and states that are no longer true.", "Use used to + base verb for repeated past actions or past states. In questions and negatives, use did and the base form: Did you use to...? We didn't use to... .", "Used to describes a past pattern that has changed or ended. Use the past simple for a single finished event.", "I used to walk to school, but now I take the bus.", "Used to describes a repeated past habit; but now marks the change.", "Make clear whether you mean a past routine, a past state or one event."],
        [['conditionals-comparison'], "Comparing zero and first conditionals", "Express general results and real future possibilities.", "Choose a conditional pattern according to whether the result is general or future.", "Use the zero conditional for rules and repeated results: if + present simple, present simple. Use the first conditional for a real future possibility: if + present simple, will or another suitable result form.", "The difference is mainly meaning. Both patterns use present simple after if; the result clause shows whether the outcome is general or future.", "If water reaches 100°C, it boils. If the weather improves, we will travel.", "The first sentence gives a general fact; the second describes a future possibility.", "Decide whether the result is always true or depends on a possible future event."],
        [['integrated-scenarios-two'], "Integrated language in practical situations", "Combine grammar, vocabulary and communication in one situation.", "Use the language choices that fit the purpose of a complete task.", "Read the situation first and identify who is speaking, what has happened and what needs to happen next. Select useful grammar and vocabulary, then connect the ideas in a logical order.", "An integrated task tests how well language works together. A sentence may be grammatically correct but still fail to answer the situation.", "The train has been delayed, so I will call the hotel and change the arrival time.", "The present perfect states the current result; so connects it to the next action.", "Plan the message around purpose, key details and next step before drafting."],
        [['opinion-reasons'], "Opinions and supporting reasons", "Express a view and explain why you hold it.", "Build a short, clear opinion with a relevant reason or example.", "Use I think, In my view or I believe to introduce a position. Add because to give a reason, and for example to make the reason concrete. Keep the opinion and its support connected.", "An opinion is not evidence by itself. A reason explains the view; a fact or example can support that reason.", "In my view, the earlier meeting is better because more people are available.", "The opinion is stated first and because introduces its reason.", "Ask whether each example supports the point you want the listener to accept."],
        [['compare-solutions', 'financial-comparison'], "Comparing options and trade-offs", "Evaluate options using clear criteria and balanced language.", "Compare costs, benefits, risks and limits before recommending a choice.", "Name the options and choose criteria such as cost, time, quality or risk. Use comparatives to explain differences, while phrases such as on the other hand introduce a trade-off. Support a recommendation with the criteria that matter most.", "The cheapest option is not always the best value. A comparison is useful only when the criteria are clear and applied fairly.", "Option A costs less, whereas Option B includes support and has a lower risk of delay.", "Whereas signals contrast between cost and support or risk.", "State the criterion, compare both sides and explain why one matters more."],
        [['medical-information-literacy'], "Reading health information critically", "Understand health information and assess its limits.", "Identify the source, purpose and evidence in a health message.", "Check who produced the information, when it was published and which group it describes. Separate a general recommendation from personal medical advice. Notice whether the text reports evidence, an opinion or a possible risk.", "One result does not prove that a treatment works for everyone. Avoid changing care based only on an isolated claim.", "The article reports an early result, but it does not say whether the study included older adults.", "But introduces a limit that affects how broadly the result can be applied.", "Check the evidence and scope of a claim before repeating it as general advice."],
        [['nominalisation'], "Nominalisation in formal writing", "Use noun forms to organise formal information.", "Recognise when a noun form makes a text concise and when it hides the action.", "Nominalisation changes a verb or adjective into a noun: decide becomes decision; effective becomes effectiveness. It can help group ideas in academic and professional writing. Keep the person responsible and the action clear.", "Noun-heavy writing can sound distant or hide who acted. A verb is often clearer when the action matters.", "The team decided to revise the plan. The decision led to a revision.", "The second sentence uses nouns to connect ideas, while the first names the action directly.", "Use nominalisation to connect information, then check that responsibility remains clear."],
        [['participial-clauses'], "Participial clauses", "Shorten sentences while keeping the relationship between actions clear.", "Use an -ing or past-participle clause with the correct subject.", "An -ing clause can show an action happening at the same time or give a reason. A past-participle clause often gives passive or completed meaning. The understood subject should normally match the subject of the main clause.", "A dangling participle creates an unclear or illogical subject. Use a full clause when shortening would make the meaning uncertain.", "Walking to the station, Maya saw the notice.", "Maya is the person walking and the person who saw the notice.", "Check who performs the action in the participial clause before shortening the sentence."],
        [['press-release-analysis'], "Analysing a press release", "Identify purpose, audience and claims in a public announcement.", "Read a press release for facts, framing and intended action.", "Identify the organisation, intended audience and main announcement. Separate verifiable details from promotional language. Notice quotations, dates and figures, then ask what context is missing and what response the writer wants.", "A press release is an organisation's communication, not an independent report. Attribute claims to their source and check them before treating them as established facts.", "The company says the new service will reduce waiting times by 20%.", "Says attributes the claim to the company rather than presenting it as independently verified.", "Report who makes a claim and identify the evidence needed to assess it."],
        [['public-consultation'], "Language for public consultation", "Present views and respond to community proposals.", "Explain a position respectfully and make a practical recommendation.", "State the issue and the people affected. Give reasons, acknowledge another concern and propose a clear action. Use should for recommendations and could for possible options. Ask precise questions when information is missing.", "Consultation invites views but does not automatically mean that every proposal will be adopted. Distinguish a suggestion from a confirmed decision.", "Residents could support the new route if the evening service is retained.", "Could support presents an option; if introduces a condition.", "Make the concern, evidence and requested action easy for decision-makers to identify."],
        [['sustainable-operations'], "Discussing sustainable operations", "Describe environmental aims and operational trade-offs.", "Compare an improvement with its costs, effects and practical limits.", "Name the action and the outcome it aims to improve. Use cause-and-effect language to explain expected benefits, and modal verbs to mark forecasts. Consider resource use, people affected, time and cost.", "An environmental benefit does not prove that an action is sustainable in every respect. State the measure, time period and limits of the claim.", "The new route may reduce fuel use, although it could increase delivery time.", "May and could mark expected effects; although shows the trade-off.", "Describe the intended benefit and the possible cost using evidence-sensitive language."],
        [['advanced-reported-claims'], "Reporting and evaluating claims", "Attribute complex claims and keep the speaker's meaning intact.", "Choose reporting verbs that show how a claim is presented.", "Use verbs such as argue, claim, suggest, acknowledge and warn to report a source. Choose the verb carefully: each one signals a different stance. Preserve qualifications, time references and the original level of certainty.", "Reporting a claim does not make it true. Avoid changing suggest into prove or removing a limitation from the original.", "The report suggests that costs may rise if demand continues.", "Suggests and may preserve the cautious force of the reported claim.", "Name the source, retain its qualifications and evaluate the support separately."],
        [['counterfactual-analysis'], "Counterfactual analysis", "Explore how a different condition might have changed an outcome.", "Separate real events from a reasoned alternative scenario.", "A counterfactual describes what might have happened under a condition that was not met. Use if + past perfect with would, could or might have + past participle. Explain the mechanism linking the imagined change to the result.", "A plausible alternative is not proof that the alternative would certainly have happened. State assumptions and uncertainty.", "If the team had checked the figures earlier, it might have found the error before publication.", "Might have marks a possible alternative result, not a certain one.", "Make the assumption visible and avoid claiming more than the scenario supports."],
        [['economics-commentary'], "Writing an economics commentary", "Explain an economic change and its possible effects.", "Connect a reported trend with a cautious interpretation.", "Name the indicator, period and comparison. Describe what changed, suggest possible factors and distinguish a relationship from a cause. Use terms such as rise, fall, remain stable and account for to present the trend clearly.", "A change in one indicator does not explain the whole economy. Check the time period, comparison and evidence before proposing a cause.", "Prices rose faster than wages during the period, which reduced purchasing power for some households.", "The clause reports a relationship and limits its scope to some households.", "Describe the data first, then label interpretation and possible explanation."],
        [['executive-recommendation'], "Executive recommendations", "Summarise an issue and recommend a practical decision.", "Give decision-makers a concise recommendation with reasons and conditions.", "Lead with the recommendation. Add the most relevant evidence, explain the expected benefit and identify risks or implementation needs. Use would for expected outcomes and should for a recommendation.", "A recommendation is not a finding. Make the evidence, assumptions and action owner clear.", "We recommend a three-month pilot because it would test the service before full implementation.", "Recommend names the action; because gives its reason; would marks the expected result.", "A useful recommendation tells the reader what to decide, why and what to monitor."],
        [['strategic-planning'], "Language for strategic planning", "Describe goals, priorities, options and implementation.", "Connect a long-term objective with practical steps and measures.", "State the objective, identify priorities and assign actions over time. Use future forms for plans, conditionals for possible changes and sequencing expressions for stages. Define how progress will be measured.", "A goal describes a desired result; an action states what someone will do. Do not confuse a target with evidence that it has been achieved.", "The team will review progress each month and adjust the plan if demand changes.", "Will review gives the planned action; if introduces a condition for adjustment.", "Link each goal to an owner, a time frame and a way to measure progress."],
        [['integrated-analysis-three', 'multisource-synthesis', 'synthesis-multiple-views', 'cross-disciplinary-synthesis'], "Synthesis across sources and viewpoints", "Combine several sources without losing their differences.", "Show where sources agree, differ or answer different questions.", "Group sources around ideas rather than summarising them one by one. Attribute each point, compare the evidence and explain how the sources relate. A synthesis can identify agreement, disagreement, gaps and different methods.", "A list of summaries is not a synthesis. Keep sources distinct and do not imply that they support the same claim when they do not.", "Both reports identify a staffing problem, but they use different measures and recommend different responses.", "But signals a difference, while both reports identifies shared ground.", "Use clear attribution and explain the relationship between each source and the central question."],
        [['register-diplomacy', 'register-shifts'], "Register and diplomatic language", "Adapt tone and directness to audience and purpose.", "Choose a level of formality that is respectful and clear.", "Consider the relationship, setting and purpose. Use direct wording for urgent instructions, and softer phrases such as could you or I would suggest for collaborative requests. Keep the key action explicit even when the tone is diplomatic.", "Polite language should not hide the decision or deadline. Excessive indirectness can make responsibility unclear.", "Could you send the revised version by Friday? We need it for the review.", "Could you softens the request; the second sentence states the reason and deadline.", "Adapt the tone while preserving the message's essential information."],
        [['critical-literature'], "Critical reading of literature", "Interpret literary choices using evidence from the text.", "Explain how voice, structure and language shape a reader's response.", "Identify the speaker, setting and conflict. Notice repeated images, contrasts and shifts in tone. Support an interpretation with a precise detail, then explain how that detail shapes the reader's understanding.", "An interpretation is not the same as a fact about the text. Consider alternative readings and connect each one to evidence.", "The repeated image of a locked door may suggest that the character feels excluded.", "May signals an interpretation, and the repeated image is its textual evidence.", "Name the feature, cite the detail and explain its effect without treating one reading as certain."],
        [['discourse-power'], "Power and agency in discourse", "Notice how language assigns responsibility and authority.", "Analyse who acts, who is affected and whose viewpoint is heard.", "Look for active and passive clauses, naming choices, modal verbs and quoted voices. These choices can foreground an actor, hide responsibility, present a rule as optional or make one viewpoint sound authoritative.", "A grammatical choice can shape emphasis, but it does not prove the speaker's intention by itself. Use context and repeated patterns to support an interpretation.", "The policy was introduced without public consultation.", "The passive foregrounds the policy and leaves the decision-maker unnamed.", "Describe the wording first, then explain its possible effect with evidence."],
        [['discourse-reformulation'], "Reformulating ideas clearly", "Restate an idea for clarity, emphasis or a new audience.", "Paraphrase accurately while preserving meaning and certainty.", "Identify the original point and its qualifications before rewriting it. Change the wording and sentence structure, keep key terms accurate and add attribution when the idea comes from a source.", "A paraphrase is not a summary if it changes the scope, and it is not accurate if it removes a condition or makes a cautious claim certain.", "Original: The results may improve in some settings. Reformulation: Some settings could show better results.", "Both versions preserve possibility and limit the claim to some settings.", "Compare the source and paraphrase for meaning, scope and level of certainty."],
        [['epistemic-responsibility'], "Responsible claims and knowledge", "Show what is known, inferred and still uncertain.", "Communicate the basis and limits of a claim honestly.", "Identify the evidence behind a statement and distinguish direct observation from interpretation. Use may, appears to or is likely to when the evidence warrants caution. Name relevant limits and avoid hiding uncertainty.", "A confident tone does not make a claim well supported. Uncertainty should be precise, not so broad that it removes useful information.", "The available records indicate a delay, although its cause remains unclear.", "Indicate attributes the statement to the records; although marks an unresolved issue.", "State the source, the supported conclusion and the open question separately."],
        [['intertextual-allusion'], "Allusion and reference across texts", "Recognise how a text refers to another work or shared idea.", "Use context to explain an allusion and its effect.", "An allusion briefly evokes a known story, person, event or phrase. Identify the possible reference, then ask what meaning it adds in this new context. Explain the link using evidence from the text.", "Do not assume every reader recognises an allusion. A plausible reference needs support from wording, context or shared cultural knowledge.", "Calling the plan a Trojan horse suggests that it may conceal a hidden risk.", "The reference evokes a story about concealed danger and adds a warning.", "Explain both the reference and its function in the present text."],
        [['investigative-reporting'], "Investigative reporting and attribution", "Present a finding with transparent sources and careful wording.", "Separate verified facts, allegations and unanswered questions.", "State what has been verified and how. Attribute allegations to their source, seek independent confirmation and distinguish documents, interviews and inference. Use past forms for established events and cautious language for unresolved claims.", "An allegation is not a verified fact. Do not remove attribution or imply that a source proves more than it does.", "Two records confirm the date; investigators have not yet established who approved the change.", "The first clause reports a verified detail; the second states what remains unknown.", "Make the evidence trail and remaining uncertainty clear to the reader."],
        [['philosophical-objection'], "Building a philosophical objection", "Test an argument by examining its premises and conclusions.", "Present a fair objection and explain what it challenges.", "Identify the claim, its premises and the link between them. Ask whether the terms are clear, whether the premises are supported and whether the conclusion follows. State the strongest reasonable objection, then explain what response might address it.", "Do not reject a conclusion only because it is unpopular. Challenge the reasoning and recognise what the argument gets right.", "The conclusion may follow if fairness means equal treatment, but the argument has not defended that definition.", "If introduces a condition; but identifies the missing defence.", "Represent the argument fairly before evaluating its assumptions and inference."],
        [['review-real-dialogues'], "Review through real communication", "Apply language choices in a complete conversation.", "Review how grammar supports a speaker's purpose and response.", "Notice how speakers ask, answer, clarify and respond. Review the form in context, then practise changing one detail while keeping the conversation natural. Pay attention to turn-taking and connected pronunciation.", "A dialogue is more than a list of correct sentences. Each line should respond to what the other person has said.", "Could you repeat the time? The meeting starts at half past six.", "The first turn requests clarification; the second provides the missing detail.", "Check meaning, response and natural interaction together."],
        [['adjective-order'], "Order of adjectives", "Place several adjectives in a natural order before a noun.", "Use adjective order to describe a person or object clearly.", "When several adjectives come before a noun, opinion often comes before size, age, shape, colour, origin, material and purpose. Speakers usually use only the adjectives needed to identify or describe the noun.", "This order is a common tendency, not a reason to overload a sentence. Coordinate equal descriptions when appropriate.", "She bought a beautiful small Italian leather bag.", "The adjectives move from opinion and size to origin and material.", "Keep the noun clear and use adjective order to make the description easy to process."],
        [['adverbs-manner'], "Adverbs of manner", "Describe how an action is performed.", "Form and position manner adverbs naturally.", "Many manner adverbs use adjective + -ly: careful becomes carefully. They often follow the verb or its object. Some common forms are irregular, including well and fast.", "Use an adjective to describe a noun and an adverb to describe an action. The ending -ly is common but not universal.", "The driver stopped carefully near the crossing.", "Carefully describes how the driver stopped.", "Locate the action first, then choose the adverb that explains how it happened."]];
        [[''], 'Clear English communication', 'Understand the topic and communicate its main ideas clearly.', 'Use the unit topic to explain a situation and support a simple point.', 'Start with the main idea. Add relevant details in a logical order and use clear sentence patterns. Check key terms, references and time relationships so the reader can follow the message.', 'Use an example that supports the point. Do not add details that distract from the purpose.', 'The team changed the schedule because several members were unavailable.', 'Because gives the reason for the decision.', 'Clear communication makes the purpose and the supporting detail easy to identify.']
    ];

    foreach ($rules as [$needles, $label, $summary, $goal, $explain, $contrast, $example, $reason, $foundation]) {
        foreach ($needles as $needle) {
            if ($needle !== '' && str_contains($slug, $needle)) {
                return [
                    'title' => $title,
                    'summary' => $summary,
                    'goal' => $goal,
                    'explain' => $explain,
                    'contrast' => $contrast,
                    'example' => $example,
                    'reason' => $reason,
                    'foundation' => $foundation,
                ];
            }
        }
    }

    return [
        'title' => $title,
        'summary' => 'A clear guide to ' . strtolower($title) . ' in English.',
        'goal' => 'Understand the main ideas and language used in ' . strtolower($title) . '.',
        'explain' => 'Start with the purpose of the message. Identify its main idea, the details that support it and the language that connects them. Read the examples carefully and notice how the structure changes the meaning.',
        'contrast' => 'Choose words and sentence forms that fit the audience and situation. Keep facts, opinions and suggestions separate. Use a clear example to show how the idea works.',
        'example' => 'The team discussed the issue and agreed on a clear next step.',
        'reason' => 'The sentence states the topic and the result in a simple order.',
        'foundation' => 'Clear English helps the reader see the main point, the reason behind it and what should happen next.',
    ];
}

function study_visual(string $slug): ?array
{
    static $visuals;
    $visuals ??= json_decode(file_get_contents(ROOT . '/content/books/visual.json'), true, 512, JSON_THROW_ON_ERROR);
    return $visuals[$slug] ?? null;
}

function study_level(string $code): ?array
{
    static $levels;
    $levels ??= [
        'a1' => [
            'title' => 'Primeras conversaciones',
            'intro' => 'Empezamos con oraciones breves y completas. Aprenderás a presentarte, hablar de tu familia y tu rutina, describir lugares y pedir lo que necesitás. Cada capítulo conecta una forma gramatical con una situación cotidiana y te pide producir tus propios mensajes.',
            'before' => 'No necesitás conocimientos previos de gramática inglesa. Tené un cuaderno para anotar vocabulario con una frase propia y escuchá los ejemplos antes de intentar repetirlos.',
            'outcomes' => ['Presentarte y preguntar por datos personales.', 'Describir hábitos, acciones actuales, capacidades y gustos.', 'Pedir cantidades, dar indicaciones y describir estados pasados.'],
            'project' => 'Prepará una guía personal de 120–160 palabras para recibir a un visitante: quién sos, cómo es tu barrio, qué hacés habitualmente, qué pueden hacer juntos y cómo llegar a un lugar. Presentala oralmente durante un minuto.',
            'review' => ['¿Cada oración tiene un sujeto y un verbo?', '¿Distingo una rutina de una acción que sucede ahora?', '¿Uso auxiliares y formas negativas sin duplicarlos?', '¿Puedo responder preguntas personales sin leer?'],
        ],
        'a2' => [
            'title' => 'Historias, decisiones y planes',
            'intro' => 'Pasamos de describir a narrar y comparar. Vas a organizar acontecimientos, crear el fondo de una historia, justificar elecciones y explicar planes. Trabajá con secuencias: una oración aislada puede ser correcta y aun así no contar bien una historia.',
            'before' => 'Repasá be, presente simple y continuo, preguntas y expresiones de cantidad. Necesitás distinguir sujeto, verbo y complemento para comparar las formas del pasado.',
            'outcomes' => ['Narrar una experiencia con una secuencia comprensible.', 'Combinar acontecimientos con acciones en desarrollo.', 'Comparar opciones y distinguir planes, ofrecimientos y predicciones.'],
            'project' => 'Escribí una crónica de 150–180 palabras de un viaje real o imaginario. Incluí lo que ocurrió, el contexto, una comparación entre dos opciones y un plan para una próxima visita. Contala en dos minutos.',
            'review' => ['¿Después de did uso el verbo base?', '¿La secuencia temporal se entiende sin adivinar?', '¿Elijo pasado simple o continuo por el significado?', '¿Puedo justificar una elección con comparativos?'],
        ],
        'b1' => [
            'title' => 'Experiencias y explicaciones',
            'intro' => 'El objetivo es desarrollar una idea más allá de una respuesta breve. Vas a relacionar pasado y presente, explicar condiciones, describir procesos y distinguir reglas de consejos. Prestá atención a qué sabe tu lector y a qué información necesita para seguirte.',
            'before' => 'Repasá pasado simple, formas futuras y participios frecuentes. Antes de avanzar, comprobá que podés narrar un episodio y formular preguntas sobre él.',
            'outcomes' => ['Vincular experiencias con un contexto temporal claro.', 'Explicar condiciones y consecuencias posibles.', 'Describir procesos y formular obligaciones, permisos y consejos.'],
            'project' => 'Redactá una guía de 180–220 palabras para incorporarse a una actividad comunitaria. Presentá tu experiencia, explicá cómo funciona la actividad y sus reglas, y proponé alternativas si cambia el plan. Respondé preguntas sobre la guía.',
            'review' => ['¿Distingo un período terminado de una experiencia hasta ahora?', '¿La condición y su consecuencia son coherentes?', '¿La pasiva tiene be y participio?', '¿Diferencio prohibición de ausencia de obligación?'],
        ],
        'b2' => [
            'title' => 'Hipótesis y perspectivas',
            'intro' => 'Trabajamos con decisiones, mensajes ajenos y descripciones complejas. Una respuesta eficaz mantiene consistencia temporal y hace explícitas las relaciones entre sus partes. Vas a reformular ideas sin cambiar involuntariamente su significado.',
            'before' => 'Necesitás manejar los tiempos básicos, el presente perfecto, la pasiva y la estructura de una cláusula. Repasá también participios e infinitivos.',
            'outcomes' => ['Distinguir hipótesis presentes de alternativas pasadas.', 'Transmitir mensajes adaptando referencias y atribución.', 'Usar relativas y patrones verbales para construir textos precisos.'],
            'project' => 'Escribí un informe de 220–260 palabras sobre una decisión de un equipo ficticio. Resumí lo que dijeron dos participantes, identificá propuestas con relativas y explorá una alternativa pasada y una actual. Defendé tu recomendación oralmente.',
            'review' => ['¿La hipótesis corresponde al período que imagino?', '¿El discurso indirecto conserva quién dijo qué y cuándo?', '¿Las relativas identifican o agregan información con claridad?', '¿Los complementos verbales mantienen el significado previsto?'],
        ],
        'c1' => [
            'title' => 'Argumentación y control del énfasis',
            'intro' => 'La precisión incluye organizar un argumento y decidir qué destacar. Vamos a trabajar con inversión, relaciones temporales complejas, atribución y cohesión. Elegí estructuras por su función: un texto avanzado no necesita que cada oración parezca complicada.',
            'before' => 'Repasá condicionales, pasivas, discurso indirecto y relaciones entre cláusulas. Debés poder sostener un argumento con ejemplos y una objeción.',
            'outcomes' => ['Controlar el énfasis según propósito y registro.', 'Relacionar causas y resultados de distintos períodos.', 'Atribuir información y construir argumentos cohesionados.'],
            'project' => 'Escribí una propuesta de 260–320 palabras sobre una mejora educativa. Incluí diagnóstico, evidencia ficticia identificada como tal, una objeción y una respuesta. Usá énfasis selectivo, atribución y una consecuencia contrafactual.',
            'review' => ['¿Cada estructura enfática cumple una función?', '¿Las relaciones temporales son interpretables?', '¿Distingo afirmaciones propias de información atribuida?', '¿Cada párrafo desarrolla una idea y enlaza con el siguiente?'],
        ],
        'c2' => [
            'title' => 'Matices, registro y estilo',
            'intro' => 'El trabajo se centra en decisiones de lenguaje: fuerza de una afirmación, foco informativo, colocaciones y formulaciones institucionales. Vas a comparar versiones y justificar cambios según destinatario, evidencia y propósito.',
            'before' => 'Necesitás control flexible de las estructuras anteriores y experiencia revisando textos extensos. Tené a mano tus propias lecturas para registrar combinaciones léxicas en contexto.',
            'outcomes' => ['Formular recomendaciones sin ambigüedad de alcance.', 'Cambiar el foco conservando el contenido esencial.', 'Ajustar certeza, colocaciones y registro a distintas audiencias.'],
            'project' => 'Prepará un informe crítico de 300–350 palabras y una adaptación pública de 120 palabras sobre una propuesta ficticia. Diferenciá hechos, inferencias y recomendaciones; justificá cinco cambios de registro entre las versiones.',
            'review' => ['¿El alcance de mis afirmaciones coincide con la evidencia?', '¿El foco conduce al lector hacia la información relevante?', '¿Las combinaciones léxicas resultan naturales y adecuadas?', '¿Puedo simplificar el registro sin deformar el argumento?'],
        ],
    ];
    return $levels[$code] ?? null;
}
